import sys

def main():
    data = sys.stdin.read().split()
    n, k = int(data[0]), int(data[1])
    a = data[2:2 + n]
    left = zeros = best = 0
    for right in range(n):
        if a[right] == '0':
            zeros += 1
        while zeros > k:
            if a[left] == '0':
                zeros -= 1
            left += 1
        if right - left + 1 > best:
            best = right - left + 1
    print(best)

